INSERT INTO projects (id, title, description, url, category, hidden, display_order, created_at) VALUES ('0ef22483-48f4-46e4-83bc-586fc9f3fcdb', 'VoxFlow Studio', 'Multi-provider neural speech studio. Synthesises and transcribes through Deepgram, Cartesia Sonic, ElevenLabs and Gemini from one desk, with an archive of every take.', 'https://voxflow-809.pages.dev', 'Web Apps', 0, 0, CURRENT_TIMESTAMP);
