INSERT INTO projects (id, title, description, url, category, hidden, display_order, created_at) VALUES ('27fa1add-c9e0-4349-9421-17cbf90367e2', 'Dubber', 'The flagship edge build of the dubbing suite. Eleven languages out, twelve voices in, running serverless on Cloudflare Workers.', 'https://dubber.atmr.workers.dev', 'Web Apps', 0, 2, CURRENT_TIMESTAMP);
